export const getListEduDiscussionTopicsUrl = (id: string,
    params?: ListEduDiscussionTopicsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/edu/courses/${id}/discussions?${stringifiedParams}` : `/api/edu/courses/${id}/discussions`
}

